  access::view_traits_impl< ::ClassStudent, id_mysql >::query_base_type
  access::view_traits_impl< ::ClassStudent, id_mysql >::
  query_statement (const query_base_type& q)
  {
    query_base_type r (
      "SELECT "
      "`tbl_classes`.`id`, "
      "`tbl_classes`.`name`, "
      "`tbl_student`.`sn`, "
      "`tbl_student`.`classId`, "
      "`tbl_student`.`name`, "
      "`tbl_student`.`age`, "
      "`tbl_student`.`score`, "
      "`tbl_student`.`birthday` ");

    r += "FROM `tbl_classes`";

    r += " LEFT JOIN `tbl_student` ON";
    // From student.hxx:102:17
    r += query_columns::Student::classId == query_columns::Classes::id;

    query_base_type c (
      // From student.hxx:103:17
      (q.empty () ? query_base_type::true_expr : q));

    c.optimize ();

    if (!c.empty ())
    {
      r += " ";
      r += c.clause_prefix ();
      r += c;
    }

    return r;
  }

